from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    store = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in store:
            return True
        _, wt = store[key]
        return t >= wt + ttl

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # remove expired entries lazily is optional, but check this key
            if key in store:
                if is_expired(key, t):
                    del store[key]
                else:
                    del store[key]  # will re-add, remove old position
                    store[key] = (value, t)
                    store.move_to_end(key)
                    continue
            # key not present (either never existed or expired)
            if len(store) >= capacity:
                # evict LRU, but skip expired ones don't count towards capacity? 
                # Expired entries count as absent for every purpose, so they shouldn't count toward capacity.
                # Need to clean expired entries first
                expired_keys = [k for k, (v, wt) in store.items() if t >= wt + ttl]
                for k in expired_keys:
                    del store[k]
                if len(store) >= capacity:
                    # evict least recently used (first in OrderedDict)
                    store.popitem(last=False)
            store[key] = (value, t)
            store.move_to_end(key)
        else:
            _, t, key = op
            if key in store and not is_expired(key, t):
                value, wt = store[key]
                store.move_to_end(key)
                results.append(value)
            else:
                if key in store:
                    del store[key]
                results.append(-1)

    return results

